  exact hpq w Frame.rel_refl $ hp w;

protected lemma bot : ¬M ⊧ ⊥ := by simp [ValidOnModel, Satisfies];

instance : Semantics.Bot (Kripke.Model) := ⟨λ _ => ValidOnModel.bot⟩

